import * as React from "react"
import { Link, useStaticQuery, graphql } from "gatsby" // useStaticQuery와 graphql 추가!

const Layout = ({ location, title, children }) => {
  const rootPath = `${__PATH_PREFIX__}/`
  const isRootPath = location.pathname === rootPath
  let header

  if (isRootPath) {
    header = (
      <h1 className="main-heading">
        <Link to="/">{title}</Link>
      </h1>
    )
  } else {
    header = (
      <Link className="header-link-home" to="/">
        {title}
      </Link>
    )
  }

// src/components/layout.js 내부
const data = useStaticQuery(graphql`
  query SidebarQuery {
    allMarkdownRemark {
      group(field: { frontmatter: { category: SELECT } }) {
        fieldValue
        totalCount
      }
    }
  }
`)

const categories = data.allMarkdownRemark.group

  return (
    <div className="global-wrapper" data-is-root-path={isRootPath}>
      <header className="global-header">{header}</header>
      
      {/* 사이드바와 메인을 감싸는 그리드 컨테이너 추가 */}
      <div className="content-container"> 
        <main>{children}</main>
        
        <aside className="sidebar">
          <section>
            <h3>Categories</h3>
            <ul>
              {categories.map(cat => (
                <li key={cat.fieldValue}>
                  <Link to={`/category/${cat.fieldValue.toLowerCase()}/`}>
                    {cat.fieldValue} ({cat.totalCount})
                  </Link>
                </li>
              ))}
            </ul>
          </section>
        </aside>
      </div>

      <footer className="global-footer">
        © {new Date().getFullYear()}, Built with
        {` `}
        <a href="https://www.gatsbyjs.com">Gatsby</a>
      </footer>
    </div>
  )
}

export default Layout